#[test]
fn library_query_matches_python() {
    use pd_filter::query::library_query;
    let Some(g) = load() else { return };
    let (mut checked, mut bad) = (0, Vec::new());
    for case in g["queries"].as_array().unwrap() {
        if case.get("error").is_some() { continue; }
        let supp: std::collections::HashMap<String, Vec<i64>> = case["supplements"].as_object().unwrap().iter()
            .map(|(k, v)| (k.clone(), v.as_array().unwrap().iter().map(|x| x.as_i64().unwrap()).collect())).collect();
        let prio: Option<Vec<String>> = case["priority"].as_array().map(|a| a.iter().map(|x| x.as_str().unwrap().to_string()).collect());
        let q = library_query(&case["state"], &supp, prio.as_deref());
        checked += 1;
        // Zest breaks ties on purpose (newest added first); Python left them to SQLite, so the comparison is made without that suffix
        let ok = q.query.strip_suffix(pd_filter::query::TIE_BREAK).unwrap_or(&q.query) == case["query"].as_str().unwrap()
            && Value::Array(q.params.clone()) == case["params"]
            && q.sort_col == case["sort_col"].as_str().unwrap()
            && q.sort_ord == case["sort_ord"].as_str().unwrap()
            && serde_json::json!(q.hidden_platforms) == case["hidden_platforms"]
            && q.active_filter_name.as_deref() == case["active_filter_name"].as_str();
        if !ok { if bad.len() < 6 { bad.push(format!("state {}\n   rust:   {:?} {:?}\n   python: {} {}", case["state"], q.query, q.params, case["query"], case["params"])); } else { bad.push(String::new()); } }
    }
    let n = bad.len();
    assert!(n == 0, "{n} of {checked} library queries differ from Python. First ones:\n{}", bad.iter().filter(|s| !s.is_empty()).cloned().collect::<Vec<_>>().join("\n"));
    println!("{checked} library queries match");
}

#[test]
fn shelf_tables_match_python() {
    use pd_filter::shelf::{BUILTIN_WHERE, SORT_COLUMNS};
    let Some(g) = load() else { return };
    let py = g["builtin_where"].as_object().unwrap();
    for (k, w) in py { if let Some(w) = w.as_str() { assert_eq!(BUILTIN_WHERE.iter().find(|(kk, _)| kk == k).map(|(_, w)| *w), Some(w), "builtin filter {k}"); } else { assert!(["clock", "completion_pie", "achievement_pie"].contains(&k.as_str()), "{k} has no SQL in Python but is not a widget"); } }
    assert_eq!(BUILTIN_WHERE.len(), py.values().filter(|w| w.is_string()).count(), "Rust has a built-in filter Python does not");
    let cols: Vec<&str> = g["sort_columns"].as_array().unwrap().iter().map(|v| v.as_str().unwrap()).collect();
    assert_eq!(SORT_COLUMNS.to_vec(), cols);
}

#[test]
fn shelf_query_matches_python() {
    use pd_filter::shelf::shelf_query;
    let Some(g) = load() else { return };
    let (mut checked, mut bad) = (0, Vec::new());
    for case in g["shelves"].as_array().unwrap() {
        if case.get("error").is_some() { continue; }
        let supp: std::collections::HashMap<String, Vec<i64>> = case["supplements"].as_object().unwrap().iter()
            .map(|(k, v)| (k.clone(), v.as_array().unwrap().iter().map(|x| x.as_i64().unwrap()).collect())).collect();
        let prio: Option<Vec<String>> = case["priority"].as_array().map(|a| a.iter().map(|x| x.as_str().unwrap().to_string()).collect());
        let r = shelf_query(&case["shelf"], &case["state"], &supp, prio.as_deref());
        checked += 1;
        let ok = match (&r, case["where"].as_str()) {
            (None, None) => true,
            (Some(q), Some(w)) => q.where_ == w && q.order.strip_suffix(pd_filter::query::TIE_BREAK).unwrap_or(&q.order) == case["order"].as_str().unwrap() && Value::Array(q.params.clone()) == case["params"],
            _ => false,
        };
        if !ok { if bad.len() < 6 { bad.push(format!("shelf {}\n   rust:   {:?}\n   python: {} | {} | {}", case["shelf"], r, case["where"], case["order"], case["params"])); } else { bad.push(String::new()); } }
    }
    let n = bad.len();
    assert!(n == 0, "{n} of {checked} shelf queries differ from Python. First ones:\n{}", bad.iter().filter(|s| !s.is_empty()).cloned().collect::<Vec<_>>().join("\n"));
    println!("{checked} shelf queries match");
}

#[test]
fn home_page_matches_python() {
    pd_filter::query::set_tie_break(false);   // these compare whole result lists with Python's, which left ties to SQLite
    use pd_filter::home::{home_rows, home_shelves, HomeRow};
    let db = &golden_db();
    if !std::path::Path::new(db).exists() { eprintln!("skipped: the project's test database {db} is not there"); return; }
    let conn = rusqlite::Connection::open_with_flags(db, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();
    let Some(g) = load() else { return };
    let (mut checked, mut bad) = (0, Vec::new());
    for case in g["home"].as_array().unwrap() {
        if case.get("error").is_some() { continue; }
        let supp: std::collections::HashMap<String, Vec<i64>> = case["supplements"].as_object().unwrap().iter()
            .map(|(k, v)| (k.clone(), v.as_array().unwrap().iter().map(|x| x.as_i64().unwrap()).collect())).collect();
        let got = home_shelves(&conn, &case["state"], &supp, None);
        let want: Vec<(String, Vec<i64>)> = case["shelves"].as_array().unwrap().iter()
            .map(|s| (s["id"].as_str().unwrap().to_string(), s["games"].as_array().unwrap().iter().map(|a| a.as_i64().unwrap()).collect())).collect();
        let got_pairs: Vec<(String, Vec<i64>)> = got.iter().map(|s| (s.id.clone(), s.appids.clone())).collect();
        let rows_got: Vec<Value> = home_rows(&case["state"]).iter().map(|r| match r {
            HomeRow::Single(id) => serde_json::json!({"type": "single", "shelf": id}),
            HomeRow::Split { shelves, row_height } => serde_json::json!({"type": "split", "shelves": shelves, "row_height": row_height}),
        }).collect();
        checked += 1;
        if got_pairs != want || Value::Array(rows_got.clone()) != case["rows"] {
            let _sizes = |v: &Vec<(String, Vec<i64>)>| v.iter().map(|(i, g)| format!("{i}:{}", g.len())).collect::<Vec<_>>().join(" ");
            let mut detail = String::new();
            for ((id, a), (_, b)) in got_pairs.iter().zip(want.iter()) {
                if a != b {
                    let first = a.iter().zip(b.iter()).position(|(x, y)| x != y);
                    let same_set = { let (mut x, mut y) = (a.clone(), b.clone()); x.sort(); y.sort(); x == y };
                    detail += &format!("\n      shelf {id}: {} vs {} games, first difference at {:?}, same games in a different order: {same_set}; rust {:?} python {:?}", a.len(), b.len(), first, &a[..a.len().min(6)], &b[..b.len().min(6)]);
                }
            }
            bad.push(format!("{}{}", case["label"], detail));
        }
    }
    assert!(bad.is_empty(), "{} of {checked} home pages differ from Python:\n{}", bad.len(), bad.join("\n"));
    println!("{checked} home page variations match");
}

#[test]
fn default_shelves_and_widget_counts_match_python() {
    use pd_filter::home::{default_shelves, widget_counts};
    let Some(g) = load() else { return };
    assert_eq!(default_shelves(), g["default_shelves"], "data/default_shelves.json is stale: rerun gen_golden.py");
    let db = &golden_db();
    if !std::path::Path::new(db).exists() { eprintln!("skipped widget counts: no test database"); return; }
    let conn = rusqlite::Connection::open_with_flags(db, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();
    let (c, a) = widget_counts(&conn);
    let case = &g["home"][0];
    let to_map = |v: &Value| -> std::collections::BTreeMap<String, i64> { v.as_object().unwrap().iter().map(|(k, n)| (k.clone(), n.as_i64().unwrap())).collect() };
    assert_eq!(c, to_map(&case["completion_counts"]), "completion counts");
    assert_eq!(a, to_map(&case["achievement_counts"]), "achievement buckets");
    println!("completion {:?} achievements {:?}", c, a);
}

#[test]
fn refill_and_shuffle_sql_match_python() {
    pd_filter::query::set_tie_break(false);   // these compare whole result lists with Python's, which left ties to SQLite
    use pd_filter::home::{refill_query, shuffle_query};
    let Some(g) = load() else { return };
    let (mut checked, mut bad) = (0, Vec::new());
    for case in g["refills"].as_array().unwrap() {
        if case.get("error").is_some() { continue; }
        let supp: std::collections::HashMap<String, Vec<i64>> = case["supplements"].as_object().unwrap().iter()
            .map(|(k, v)| (k.clone(), v.as_array().unwrap().iter().map(|x| x.as_i64().unwrap()).collect())).collect();
        let (shelf, state) = (&case["shelf"], &case["state"]);
        let got = if case["kind"] == "refill" {
            let exclude: Vec<i64> = case["body"]["exclude_appids"].as_array().unwrap().iter().map(|x| x.as_i64().unwrap()).collect();
            refill_query(shelf, state, &supp, None, &exclude, case["body"].get("limit").and_then(|v| v.as_i64()))
        } else { shuffle_query(shelf, state, &supp, None) };
        let want = case["calls"].as_array().unwrap();
        checked += 1;
        let ok = match (&got, want.first()) {
            (None, None) => true,
            (Some(q), Some(w)) => q.sql == w[0].as_str().unwrap() && Value::Array(q.params.clone()) == w[1],
            _ => false,
        };
        if !ok && bad.len() < 6 { bad.push(format!("{} {}\n   rust:   {:?}\n   python: {}", case["kind"], case["body"], got.as_ref().map(|q| (&q.sql, &q.params)), serde_json::to_string(want).unwrap())); }
    }
    assert!(bad.is_empty(), "{} refill/shuffle queries differ from Python:\n{}", bad.len(), bad.join("\n"));
    println!("{checked} refill/shuffle queries match");
}

#[test]
fn pick6_matches_python() {
    use pd_filter::pick::{fetch_pick_data, pick_games, PickParams, Profile};
    let db = &golden_db();
    if !std::path::Path::new(db).exists() { eprintln!("skipped: no test database"); return; }
    let conn = rusqlite::Connection::open_with_flags(db, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();
    let Some(g) = load() else { return };
    let (now, real) = (g["fixed_now"].as_f64().unwrap(), g["real_state"].clone());
    let supp: std::collections::HashMap<String, Vec<i64>> = [("icaio_ga".to_string(), vec![440, 730, 10]), ("icaio_wl".to_string(), vec![220, 400])].into_iter().collect();
    let (mut checked, mut bad, mut with_picks) = (0, Vec::new(), 0);
    for case in g["picks"].as_array().unwrap() {
        if case.get("error").is_some() { continue; }
        let mut state = real.clone();
        for (k, v) in case["patch"].as_object().unwrap() { state[k] = v.clone(); }
        let b = &case["body"];
        let f = |k: &str, d: f64| b.get(k).and_then(|v| v.as_f64()).unwrap_or(d);
        let bound = |k: &str| b.get(k).and_then(|v| v.as_f64());
        let params = PickParams { mode: b["mode"].as_str().unwrap().to_string(), w_tags: f("w_tags", 65.0), w_review: f("w_review", 35.0), w_staleness: f("w_staleness", 0.0),
            w_recency: f("w_recency", 0.0), w_hltb: f("w_hltb", 0.0), b_review: bound("b_review"), b_staleness: bound("b_staleness"), b_recency: bound("b_recency"), b_hltb: bound("b_hltb") };
        let statuses: Option<Vec<String>> = b.get("statuses").and_then(|v| v.as_array()).map(|a| a.iter().map(|x| x.as_str().unwrap().to_string()).collect());
        let want = &case["result"];
        let data = match fetch_pick_data(&conn, &state, b["use_filtered"].as_bool().unwrap_or(false), statuses.as_deref(), &supp, None) {
            Ok(d) => d, Err(e) => { bad.push(format!("fetch failed: {e} for {b}")); continue; }
        };
        if data.games.is_empty() { checked += 1; if want.get("error").is_none() { bad.push(format!("Rust found no games, Python picked: {b}")); } continue; }
        let vals: Vec<f64> = case["rand"].as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect();
        let used = std::cell::Cell::new(0usize);
        let mut rng = || { let v = vals[used.get()]; used.set(used.get() + 1); v };
        let profile = Profile { liked: &data.liked, library_tags: &data.library_tags, using_fallback: data.using_fallback };
        let got = pick_games(&data.games, &profile, &state, &params, now, 2026, &mut rng);
        checked += 1;
        let got_json = serde_json::json!({
            "picks": got.picks.iter().map(|p| serde_json::json!({"appid": p.appid, "reason": p.reason, "bounds_relaxed": p.bounds_relaxed})).collect::<Vec<_>>(),
            "pool_size": got.pool_size, "bounded_pool_size": got.bounded_pool_size, "bounds_relaxed": got.bounds_relaxed });
        if want.get("picks").is_some() { with_picks += 1; }
        if got_json != *want || used.get() as u64 != case["consumed"].as_u64().unwrap() {
            if bad.len() < 5 { bad.push(format!("body {b} patch {}\n   rust:   {} (random numbers used {})\n   python: {} (used {})", case["patch"], got_json, used.get(), want, case["consumed"])); } else { bad.push(String::new()); }
        }
    }
    assert!(bad.is_empty(), "{} of {checked} pick cases differ from Python:\n{}", bad.len(), bad.iter().filter(|s| !s.is_empty()).cloned().collect::<Vec<_>>().join("\n"));
    println!("{checked} Pick 6 cases match ({with_picks} with picks)");
}
